@mixin theme-variant($mode) {
  @if $mode == 'light' {
    background-color: #ffffff;
    color: #111827;
  } @else if $mode == 'dark' {
    background-color: #1f2937;
    color: #f9fafb;
  } @else if $mode == 'high-contrast' {
    background-color: #000000;
    color: #ffff00;
    border: 2px solid #ffffff;
  } @else {
    background-color: #f3f4f6;
    color: #374151;
  }
}

.app-panel {
  @include theme-variant('dark');
}

// 'through' includes the end number (1, 2, 3, 4)
// 'to' excludes the end number (1, 2, 3)

$total-columns: 4;

@for $i from 1 through $total-columns {
  .col-#{$i} {
    width: ($i / $total-columns) * 100%;
    display: inline-block;
  }
}

$font-size: 64px;
$step: 1;

@while $font-size >= 16px {
  .heading-scale-#{$step} {
    font-size: $font-size;
  }

  // Decrement font size and increment step counter
  $font-size: $font-size / 2;
  $step: $step + 1;
}

@use 'sass:math';

@mixin set-grid-gap($gap-size) {
  // 1. @debug: Prints diagnostic information to terminal console for troubleshooting
  @debug "Evaluating grid gap parameter: #{$gap-size}";

  // 2. @warn: Alerts developer of deprecations or sub-optimal practices without halting build
  @if $gap-size > 64px {
    @warn "Gap size #{$gap-size} is unusually large and may break responsive layouts.";
  }

  // 3. @error: Throws a fatal compiler error and stops compilation immediately
  @if math.is-unitless($gap-size) {
    @error "Invalid argument: $gap-size must have a unit (e.g., px, rem). Received: #{$gap-size}";
  }

  gap: $gap-size;
}
